import json
import sys

# Read the last portion of the jsonl file to find recent context
with open('messages.jsonl', 'r') as f:
    lines = f.readlines()

print(f'Total messages: {len(lines)}')
print('Last 10 messages:')
for i, line in enumerate(lines[-10:]):
    try:
        msg = json.loads(line)
        role = msg.get('role', 'unknown')
        content = msg.get('content', '')
        if isinstance(content, list):
            text_parts = []
            for part in content:
                if isinstance(part, dict):
                    if part.get('type') == 'text':
                        text_parts.append(part.get('text', '')[:300])
                    elif part.get('type') == 'tool_use':
                        text_parts.append(f'[tool_use: {part.get(\"name\",\"\")} input={json.dumps(part.get(\"input\",{}), ensure_ascii=False)[:200]}]')
                    elif part.get('type') == 'tool_result':
                        tr = part.get('content', '')
                        if isinstance(tr, list):
                            tr = ' '.join([t.get('text','')[:150] for t in tr if isinstance(t, dict)])
                        text_parts.append(f'[tool_result: {str(tr)[:200]}]')
            content = ' | '.join(text_parts)
        elif isinstance(content, str):
            content = content[:300]
        print(f'---[{len(lines)-10+i}] role={role}---')
        print(content[:500])
    except Exception as e:
        print(f'[msg {i} parse error: {e}]')
" 2>&1 | head -150

