def drain(t):
    end=time.time()+t
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.1)
        if r: os.read(fd,4096)
def send(cmd, wait=2.0):
    os.write(fd,(cmd+'\r\n').encode())
    end=time.time()+wait; got=b''
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.2)
        if r:
            d=os.read(fd,4096)
            if d: got+=d
    return got
try:
    a=termios.tcgetattr(fd); a[3]&=~termios.ECHO; a[2]=a[2]&~termios.CSIZE|termios.CS8; a[4]=termios.B921600; a[5]=termios.B921600
    termios.tcsetattr(fd, termios.TCSANOW, a); termios.tcflush(fd, termios.TCIOFLUSH)
    end=time.time()+5; got=b''
