EXPORTERS = {
    "accnet_v3": export_accnet_v3,
    "attengru_v3": export_attengru_v3,
    "sleeping1": export_sleeping1,
}


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Export .bin input/reference fixtures for accnet/attengru/sleeping"
    )
    parser.add_argument("model", choices=sorted(EXPORTERS) + ["all"],
                        help="which model fixture to export, or 'all'")
    parser.add_argument("--dest", type=Path, default=None,
                        help="output directory (default: <model>_fixtures/ under repo)")
    parser.add_argument("--csv", default="sleepdata1.csv",
                        help="CSV file name for sleeping (default: sleepdata1.csv)")
    args = parser.parse_args()

    if args.model == "all":
        for name, fn in EXPORTERS.items():
            d = args.dest or (REPO_ROOT / f"PTQ_scripts/{name}_fixtures")
            print(f"\n=== {name} -> {d} ===")
            if name == "sleeping1":
                fn(d, csv_name=args.csv)
            else:
                fn(d)
        return

    dest = args.dest or (REPO_ROOT / f"PTQ_scripts/{args.model}_fixtures")
    if args.model == "sleeping1":
        export_sleeping1(dest, csv_name=args.csv)
    else:
        EXPORTERS[args.model](dest)

