127	    TfLiteTypeSizeOf(input->type, &element_size);
128	    size_t num_elements = input->bytes / element_size;
129	
130	    for (size_t j = 0; j < num_elements; ++j) {
131	      switch (element_size) {
132	        case 1: {  // int8_t, uint8_t
133	          std::uniform_int_distribution<uint32_t> dist(0, 255);
134	          input->data.uint8[j] = static_cast<uint8_t>(dist(eng));
135	          break;
136	        }
137	        case 4: {  // float, int32_t
138	          std::uniform_real_distribution<float> dist(-1.0f, 1.0f);
139	          input->data.f[j] = dist(eng);
140	          break;
141	        }
142	        default:
143	          MicroPrintf("Unsupported input tensor type: %d\n", input->type);
144	          memset(input->data.raw + j * element_size, 0, element_size);
145	          break;
146	      }
147	    }
148	  }
149	}
