161	bool ReadFile(const char* file_name, void* buffer, size_t buffer_size) {
162	  std::unique_ptr<FILE, FileCloser> file(fopen(file_name, "rb"));
163	  if (!file) {
164	    MicroPrintf("Unable to open model file: %s", file_name);
165	    return false;
166	  }
167	
168	  const size_t bytes_read =
169	      fread(buffer, sizeof(char), buffer_size, file.get());
170	  if (ferror(file.get())) {
171	    MicroPrintf("Unable to read model file: %d", ferror(file.get()));
172	    return false;
173	  }
174	  if (!feof(file.get())) {
175	    MicroPrintf("Model buffer (%d bytes) is too small.", buffer_size);
176	    return false;
177	  }
178	  if (bytes_read == 0) {
179	    MicroPrintf("No bytes read from model file.");
180	    return false;
181	  }
182	
183	  return true;
184	}
