186	bool BuildSearchPath(const char* root, const char* file_name, char* path,
187	                     size_t path_size) {
188	  const int written = snprintf(path, path_size, "%s/%s", root, file_name);
189	  if (written < 0 || static_cast<size_t>(written) >= path_size) {
190	    printf("ERROR: path is too long: %s/%s\n", root, file_name);
191	    return false;
192	  }
193	  return true;
194	}
