224	uint8_t* ReadDataFile(const char* path, size_t* out_size) {
225	  std::unique_ptr<FILE, FileCloser> file(fopen(path, "rb"));
226	  if (!file || fseek(file.get(), 0, SEEK_END) != 0) {
227	    return nullptr;
228	  }
229	
230	  const long file_size = ftell(file.get());
231	  if (file_size <= 0 || fseek(file.get(), 0, SEEK_SET) != 0) {
232	    return nullptr;
233	  }
234	
235	  uint8_t* data = static_cast<uint8_t*>(malloc(file_size));
236	  if (data == nullptr) {
237	    printf("ERROR: malloc(%ld) failed for %s\n", file_size, path);
238	    return nullptr;
239	  }
240	
241	  const size_t bytes_read =
242	      fread(data, 1, static_cast<size_t>(file_size), file.get());
243	  if (bytes_read != static_cast<size_t>(file_size)) {
244	    printf("ERROR: read %zu/%ld from %s\n", bytes_read, file_size, path);
245	    free(data);
246	    return nullptr;
247	  }
248	
249	  *out_size = bytes_read;
250	  printf("Loaded %s (%zu bytes)\n", path, bytes_read);
251	  return data;
252	}
