283	constexpr uint32_t kCrctabLen = 256;
284	uint32_t crctab[kCrctabLen];
285	
286	void GenCRC32Table() {
287	  constexpr uint32_t kPolyN = 0xEDB88320;
288	  for (size_t index = 0; index < kCrctabLen; index++) {
289	    crctab[index] = index;
290	    for (int i = 0; i < 8; i++) {
291	      if (crctab[index] & 1) {
292	        crctab[index] = (crctab[index] >> 1) ^ kPolyN;
293	      } else {
294	        crctab[index] >>= 1;
295	      }
296	    }
297	  }
298	}
299	
300	uint32_t ComputeCRC32(const uint8_t* data, const size_t data_length) {
301	  uint32_t crc32 = ~0U;
302	
303	  for (size_t i = 0; i < data_length; i++) {
304	    // crctab is an array of 256 32-bit constants
305	    const uint32_t index = (crc32 ^ data[i]) & (kCrctabLen - 1);
306	    crc32 = (crc32 >> 8) ^ crctab[index];
307	  }
308	
309	  // invert all bits of result
310	  crc32 ^= ~0U;
311	  return crc32;
312	}
313	
314	void ShowOutputCRC32(tflite::MicroInterpreter* interpreter) {
315	  GenCRC32Table();
316	  for (size_t i = 0; i < interpreter->outputs_size(); ++i) {
317	    TfLiteTensor* output = interpreter->output_tensor(i);
318	    uint8_t* output_values = tflite::GetTensorData<uint8_t>(output);
319	    uint32_t crc32_value = ComputeCRC32(output_values, output->bytes);
320	    MicroPrintf("Output CRC32: 0x%X", crc32_value);
321	  }
322	}
323	
324	void ShowInputCRC32(tflite::MicroInterpreter* interpreter) {
325	  GenCRC32Table();
326	  for (size_t i = 0; i < interpreter->inputs_size(); ++i) {
327	    TfLiteTensor* input = interpreter->input_tensor(i);
328	    uint8_t* input_values = tflite::GetTensorData<uint8_t>(input);
329	    uint32_t crc32_value = ComputeCRC32(input_values, input->bytes);
330	    MicroPrintf("Input CRC32: 0x%X", crc32_value);
331	  }
332	}
