342	bool TensorHasShape(const TfLiteTensor* tensor,
343	                    std::initializer_list<int> expected_shape) {
344	  if (tensor == nullptr || tensor->dims == nullptr ||
345	      tensor->dims->size != static_cast<int>(expected_shape.size())) {
346	    return false;
347	  }
348	
349	  int dimension = 0;
350	  for (const int expected : expected_shape) {
351	    if (tensor->dims->data[dimension++] != expected) {
352	      return false;
353	    }
354	  }
355	  return true;
356	}
