358	bool SetPnetInput(RecordingMicroInterpreter& interpreter,
359	                  const uint8_t* input_data, size_t input_size) {
360	  if (interpreter.inputs_size() != 1) {
361	    printf("ERROR: PNet benchmark requires exactly one input, got %zu\n",
362	           interpreter.inputs_size());
363	    return false;
364	  }
365	
366	  TfLiteTensor* input = interpreter.input_tensor(0);
367	  const bool valid_input_shape = TensorHasShape(input, {1, 1, 256}) ||
368	                                 TensorHasShape(input, {1, 4, 256});
369	  if (input == nullptr || input->type != kTfLiteFloat32 ||
370	      !valid_input_shape) {
371	    printf("ERROR: PNet input must be FLOAT32 [1,1,256] or [1,4,256]\n");
372	    return false;
373	  }
374	  if (input->bytes != input_size) {
375	    printf("ERROR: input size mismatch: %d vs %zu\n",
376	           static_cast<int>(input->bytes), input_size);
377	    return false;
378	  }
379	
380	  memcpy(input->data.raw, input_data, input_size);
381	  return true;
382	}
383	
384	bool ValidatePnetOutput(RecordingMicroInterpreter& interpreter,
385	                        const uint8_t* reference_data,
386	                        size_t reference_size) {
387	  if (interpreter.outputs_size() != 1) {
388	    printf("ERROR: PNet benchmark requires exactly one output, got %zu\n",
389	           interpreter.outputs_size());
390	    return false;
391	  }
392	
393	  TfLiteTensor* output = interpreter.output_tensor(0);
394	  if (output == nullptr || output->type != kTfLiteFloat32 ||
395	      !TensorHasShape(output, {1, 1, 64})) {
396	    printf("ERROR: PNet output must be FLOAT32 [1,1,64]\n");
397	    return false;
398	  }
399	  if (output->bytes != reference_size ||
400	      reference_size % sizeof(float) != 0) {
401	    printf("ERROR: output size mismatch: %d vs %zu\n",
402	           static_cast<int>(output->bytes), reference_size);
403	    return false;
404	  }
405	
406	  const float* actual = reinterpret_cast<const float*>(output->data.raw);
407	  const float* reference =
408	      reinterpret_cast<const float*>(reference_data);
409	  const size_t count = reference_size / sizeof(float);
410	  if (count == 0) {
411	    printf("ERROR: empty PNet reference output\n");
412	    return false;
413	  }
414	
415	  float max_diff = 0.0f;
416	  float sum_diff = 0.0f;
417	  size_t max_index = 0;
418	  for (size_t i = 0; i < count; ++i) {
419	    if (!std::isfinite(actual[i]) || !std::isfinite(reference[i])) {
420	      printf("ERROR: non-finite output/reference at index %zu\n", i);
421	      return false;
422	    }
423	    const float diff = std::fabs(actual[i] - reference[i]);
424	    sum_diff += diff;
425	    if (diff > max_diff) {
426	      max_diff = diff;
427	      max_index = i;
428	    }
429	  }
430	
431	  printf("[hr_pnet] first8 got: ");
432	  for (size_t i = 0; i < count && i < 8; ++i) {
433	    printf("%.4f ", static_cast<double>(actual[i]));
434	  }
435	  printf("\n");
436	  printf("[hr_pnet] n=%zu max_abs_diff=%.6f mean_abs_diff=%.6f "
437	         "worst@%zu got=%.4f ref=%.4f\n",
438	         count, static_cast<double>(max_diff),
439	         static_cast<double>(sum_diff / count), max_index,
440	         static_cast<double>(actual[max_index]),
441	         static_cast<double>(reference[max_index]));
442	
443	  constexpr float kTolerance = 1e-2f;
444	  if (max_diff > kTolerance) {
445	    printf("FAIL: max_abs_diff %.6f > %.6f\n",
446	           static_cast<double>(max_diff), static_cast<double>(kTolerance));
447	    return false;
448	  }
449	
450	  printf("PASS: hr_pnet_test\n");
451	  return true;
452	}
453	
454	int Benchmark(const uint8_t* model_data, tflite::PrettyPrintType print_type,
455	              const uint8_t* input_data, size_t input_size,
456	              const uint8_t* reference_data, size_t reference_size,
457	              const char* pnet_variant) {
458	  static Profiler profiler;
459	  static Profiler profiler2;
460	  profiler.ClearEvents();
461	  profiler2.ClearEvents();
462	  TfLiteStatus status;
463	  const bool pnet_mode = input_data != nullptr && reference_data != nullptr;
464	  struct PnetAbResultReporter {
465	    PnetAbResultReporter(bool enabled_in, const char* variant_in)
466	        : enabled(enabled_in),
467	          variant(variant_in),
468	          total_ticks(0),
469	          passed(false),
470	          emitted(false) {}
471	
472	    ~PnetAbResultReporter() { Emit(); }
473	
474	    void Emit() {
475	      if (enabled && !emitted) {
476	        printf("AB_RESULT variant=%s total_ticks=%lu pass=%d\n", variant,
477	               static_cast<unsigned long>(total_ticks), passed ? 1 : 0);
478	        emitted = true;
479	      }
480	    }
481	
482	    bool enabled;
483	    const char* variant;
484	    uint32_t total_ticks;
485	    bool passed;
486	    bool emitted;
487	  } ab_result(pnet_mode, pnet_variant);
488	  if ((input_data == nullptr) != (reference_data == nullptr)) {
489	    MicroPrintf("PNet benchmark requires both input and reference data");
490	    return -1;
491	  }
492	
493	// use this to keep the application size stable regardless of whether
494	// compression is being used
495	#ifdef USE_TFLM_COMPRESSION
496	  constexpr bool using_compression = true;
497	#else   // USE_TFLM_COMPRESSION
498	  constexpr bool using_compression = false;
499	#endif  // USE_TFLM_COMPRESSION
500	
501	  auto tensor_arena = make_aligned_alloc<16>(kTensorArenaSize);
502	  if (tensor_arena == nullptr) {
503	    MicroPrintf("Failed to allocate tensor arena");
504	    return -1;
505	  }
506	
507	  uint32_t event_handle = profiler.BeginEvent("tflite::GetModel");
508	  const tflite::Model* model = tflite::GetModel(model_data);
509	  profiler.EndEvent(event_handle);
510	
511	  event_handle = profiler.BeginEvent("tflite::CreateOpResolver");
512	  TflmOpResolverNoSignal op_resolver;
513	  status = CreateOpResolverNoSignal(op_resolver);
514	  if (status != kTfLiteOk) {
515	    MicroPrintf("tflite::CreateOpResolver failed");
516	    return -1;
517	  }
518	  profiler.EndEvent(event_handle);
519	
520	  event_handle = profiler.BeginEvent("tflite::RecordingMicroAllocator::Create");
521	  tflite::RecordingMicroAllocator* allocator(
522	      tflite::RecordingMicroAllocator::Create(tensor_arena.get(), kTensorArenaSize));
523	  profiler.EndEvent(event_handle);
524	  event_handle = profiler.BeginEvent("tflite::MicroInterpreter instantiation");
525	  tflite::RecordingMicroInterpreter interpreter(
526	      model, op_resolver, allocator,
527	      tflite::MicroResourceVariables::Create(allocator, kNumResourceVariable),
528	      &profiler);
529	  profiler.EndEvent(event_handle);
530	
531	#ifdef USE_ALT_DECOMPRESSION_MEM
532	  event_handle =
533	      profiler.BeginEvent("tflite::MicroInterpreter::SetDecompressionMemory");
534	  std::initializer_list<tflite::MicroContext::AlternateMemoryRegion>
535	      alt_memory_region = {{g_alt_memory, kAltMemorySize}};
536	  status = interpreter.SetDecompressionMemory(alt_memory_region);
537	  if (status != kTfLiteOk) {
538	    MicroPrintf("tflite::MicroInterpreter::SetDecompressionMemory failed");
539	    return -1;
540	  }
541	  profiler.EndEvent(event_handle);
542	#endif  // USE_ALT_DECOMPRESSION_MEM
543	
544	  event_handle =
545	      profiler.BeginEvent("tflite::MicroInterpreter::AllocateTensors");
546	  status = interpreter.AllocateTensors();
547	  if (status != kTfLiteOk) {
548	    MicroPrintf("tflite::MicroInterpreter::AllocateTensors failed");
549	    return -1;
550	  }
551	  profiler.EndEvent(event_handle);
552	
553	  if (pnet_mode && !SetPnetInput(interpreter, input_data, input_size)) {
554	    return -1;
555	  }
556	
557	  profiler.LogTicksPerTagCsv();
558	  profiler.ClearEvents();
559	
560	#if 0
561	  if (using_compression) {
562	    status = interpreter.SetAlternateProfiler(&profiler2);
563	    if (status != kTfLiteOk) {
564	      MicroPrintf("tflite::MicroInterpreter::SetAlternateProfiler failed");
565	      return -1;
566	    }
567	  }
568	#endif
569	
570	  MicroPrintf("");  // null MicroPrintf serves as a newline.
571	
572	  // For streaming models, the interpreter will return kTfLiteAbort if the
573	  // model does not yet have enough data to make an inference. As such, we
574	  // need to invoke the interpreter multiple times until we either receive an
575	  // error or kTfLiteOk. This loop also works for non-streaming models, as
576	  // they'll just return kTfLiteOk after the first invocation.
577	  uint32_t seed = kRandomSeed;
578	  bool validation_passed = true;
579	  uint32_t inference_ticks = 0;
580	  while (true) {
581	    if (!pnet_mode) {
582	      SetRandomInput(seed++, interpreter);
583	    }
584	    ShowInputCRC32(&interpreter);
585	    MicroPrintf("");  // null MicroPrintf serves as a newline.
586	
587	    status = interpreter.Invoke();
588	    if ((status != kTfLiteOk) && (static_cast<int>(status) != kTfLiteAbort)) {
589	      MicroPrintf("Model interpreter invocation failed: %d\n", status);
590	      if (!pnet_mode) {
591	        return -1;
592	      }
593	    }
594	    inference_ticks = profiler.GetTotalTicks();
595	    ab_result.total_ticks = inference_ticks;
596	
597	    profiler.Log();
598	    MicroPrintf("");  // null MicroPrintf serves as a newline.
599	    profiler.LogTicksPerTagCsv();
600	    MicroPrintf("");  // null MicroPrintf serves as a newline.
601	    profiler.ClearEvents();
602	
603	    if (using_compression) {
604	      profiler2.Log();
605	      MicroPrintf("");  // null MicroPrintf serves as a newline.
606	      profiler2.LogTicksPerTagCsv();
607	      MicroPrintf("");  // null MicroPrintf serves as a newline.
608	      profiler2.ClearEvents();
609	    }
610	
611	    ShowOutputCRC32(&interpreter);
612	    MicroPrintf("");  // null MicroPrintf serves as a newline.
613	
614	    if (pnet_mode) {
615	      if (status != kTfLiteOk) {
616	        printf("ERROR: PNet benchmark requires one complete invocation\n");
617	        validation_passed = false;
618	      } else {
619	        validation_passed =
620	            ValidatePnetOutput(interpreter, reference_data, reference_size);
621	      }
622	      ab_result.passed = validation_passed;
623	      ab_result.Emit();
624	    }
625	
626	    if (status == kTfLiteOk || pnet_mode) {
627	      break;
628	    }
629	  }
630	
631	  LogAllocatorEvents(*allocator, print_type);
632	  MicroPrintf("TFLM benchmarking done!");
633	  MicroPrintf("");  // null MicroPrintf serves as a newline.
634	
635	  return validation_passed ? 0 : -1;
636	}
