47	bool RunDirectConv1Comparison(const char* input_file, const char* filter_file,
48	                              const char* bias_file, float* max_abs_error) {
49	  constexpr size_t kInputCount = 32;
50	  constexpr size_t kInputElements = 1 * 1 * 276 * 1;
51	  constexpr size_t kFilterElements = 32 * 1 * 21 * 1;
52	  constexpr size_t kBiasElements = 32;
53	  constexpr size_t kOutputElements = 1 * 1 * 128 * 32;
54	  constexpr size_t kInputBytes =
55	      kInputCount * kInputElements * sizeof(float);
56	  constexpr size_t kFilterBytes = kFilterElements * sizeof(float);
57	  constexpr size_t kBiasBytes = kBiasElements * sizeof(float);
58	  constexpr size_t kOutputBytes = kOutputElements * sizeof(float);
59	  constexpr float kDirectTolerance = 1e-5f;
60	
61	  size_t input_size = 0;
62	  size_t filter_size = 0;
63	  size_t bias_size = 0;
64	  uint8_t* input_buf =
65	      tflm_test_util::LoadDataFile(input_file, &input_size);
66	  uint8_t* filter_buf = nullptr;
67	  uint8_t* bias_buf = nullptr;
68	  float* reference_output = nullptr;
69	  float* cmsis_output = nullptr;
70	  void* scratch = nullptr;
71	
72	  auto cleanup = [&]() {
73	    free(scratch);
74	    free(cmsis_output);
75	    free(reference_output);
76	    free(bias_buf);
77	    free(filter_buf);
78	    free(input_buf);
79	  };
80	
81	  if (input_buf == nullptr) {
82	    cleanup();
83	    return false;
84	  }
85	  filter_buf = tflm_test_util::LoadDataFile(filter_file, &filter_size);
86	  if (filter_buf == nullptr) {
87	    cleanup();
88	    return false;
89	  }
90	  bias_buf = tflm_test_util::LoadDataFile(bias_file, &bias_size);
91	  if (bias_buf == nullptr) {
92	    cleanup();
93	    return false;
94	  }
95	
96	  if (input_size != kInputBytes || filter_size != kFilterBytes ||
97	      bias_size != kBiasBytes) {
98	    printf("ERROR: direct Conv1 fixture sizes input=%zu/%zu filter=%zu/%zu "
99	           "bias=%zu/%zu\n",
100	           input_size, kInputBytes, filter_size, kFilterBytes, bias_size,
101	           kBiasBytes);
102	    cleanup();
103	    return false;
104	  }
105	
106	  reference_output = static_cast<float*>(malloc(kOutputBytes));
107	  cmsis_output = static_cast<float*>(malloc(kOutputBytes));
108	  if (reference_output == nullptr || cmsis_output == nullptr) {
109	    printf("ERROR: direct Conv1 output allocation failed\n");
110	    cleanup();
111	    return false;
112	  }
113	
114	  tflite::ConvParams reference_params = {};
115	  reference_params.stride_height = 1;
116	  reference_params.stride_width = 2;
117	  reference_params.dilation_height_factor = 1;
118	  reference_params.dilation_width_factor = 1;
119	  reference_params.padding_type = tflite::PaddingType::kValid;
120	  reference_params.padding_values.height = 0;
121	  reference_params.padding_values.width = 0;
122	  reference_params.float_activation_min = 0.0f;
123	  reference_params.float_activation_max = FLT_MAX;
124	
125	  const int32_t reference_input_dims[] = {1, 1, 276, 1};
126	  const int32_t reference_filter_dims[] = {32, 1, 21, 1};
127	  const int32_t reference_bias_dims[] = {32};
128	  const int32_t reference_output_dims[] = {1, 1, 128, 32};
129	  const tflite::RuntimeShape reference_input_shape(4, reference_input_dims);
130	  const tflite::RuntimeShape reference_filter_shape(4, reference_filter_dims);
131	  const tflite::RuntimeShape reference_bias_shape(1, reference_bias_dims);
132	  const tflite::RuntimeShape reference_output_shape(4, reference_output_dims);
133	
134	  cmsis_nn_conv_params_f32 cmsis_params = {};
135	  cmsis_params.stride.h = 1;
136	  cmsis_params.stride.w = 2;
137	  cmsis_params.padding.h = 0;
138	  cmsis_params.padding.w = 0;
139	  cmsis_params.dilation.h = 1;
140	  cmsis_params.dilation.w = 1;
141	  cmsis_params.activation.min = 0.0f;
142	  cmsis_params.activation.max = FLT_MAX;
143	  cmsis_params.weight_format = ARM_NN_WEIGHT_FORMAT_STANDARD;
144	  const cmsis_nn_dims cmsis_input_dims = {1, 1, 276, 1};
145	  const cmsis_nn_dims cmsis_filter_dims = {32, 1, 21, 1};
146	  const cmsis_nn_dims cmsis_bias_dims = {1, 1, 1, 32};
147	  const cmsis_nn_dims cmsis_output_dims = {1, 1, 128, 32};
148	
149	  const int32_t scratch_size = arm_convolve_f32_get_buffer_size(
150	      &cmsis_params, &cmsis_input_dims, &cmsis_filter_dims,
151	      &cmsis_output_dims, ARM_NN_LAYOUT_NHWC);
152	  if (scratch_size < 0) {
153	    printf("ERROR: direct Conv1 invalid scratch size %ld\n",
154	           static_cast<long>(scratch_size));
155	    cleanup();
156	    return false;
157	  }
158	  if (scratch_size > 0) {
159	    scratch = malloc(static_cast<size_t>(scratch_size));
160	    if (scratch == nullptr) {
161	      printf("ERROR: direct Conv1 scratch allocation failed (%ld bytes)\n",
162	             static_cast<long>(scratch_size));
163	      cleanup();
164	      return false;
165	    }
166	  }
167	  cmsis_nn_context cmsis_context = {};
168	  cmsis_context.buf = scratch;
169	  cmsis_context.size = scratch_size;
170	
171	  const float* inputs = reinterpret_cast<const float*>(input_buf);
172	  const float* filter = reinterpret_cast<const float*>(filter_buf);
173	  const float* bias = reinterpret_cast<const float*>(bias_buf);
174	  float direct_max_abs_error = 0.0f;
175	  for (size_t sample = 0; sample < kInputCount; ++sample) {
176	    const float* sample_input = inputs + sample * kInputElements;
177	    tflite::reference_ops::Conv(
178	        reference_params, reference_input_shape, sample_input,
179	        reference_filter_shape, filter, reference_bias_shape, bias,
180	        reference_output_shape, reference_output, tflite::RuntimeShape(),
181	        nullptr);
182	    const arm_cmsis_nn_status status = arm_convolve_f32(
183	        &cmsis_context, &cmsis_params, &cmsis_input_dims, sample_input,
184	        &cmsis_filter_dims, filter, &cmsis_bias_dims, bias,
185	        &cmsis_output_dims, cmsis_output, ARM_NN_LAYOUT_NHWC);
186	    if (status != ARM_CMSIS_NN_SUCCESS) {
187	      printf("ERROR: direct Conv1 CMSIS failure at sample %zu status=%d\n",
188	             sample, static_cast<int>(status));
189	      cleanup();
190	      return false;
191	    }
192	
193	    for (size_t element = 0; element < kOutputElements; ++element) {
194	      const float reference_value = reference_output[element];
195	      const float cmsis_value = cmsis_output[element];
196	      const float difference = std::fabs(reference_value - cmsis_value);
197	      if (!std::isfinite(reference_value) || !std::isfinite(cmsis_value) ||
198	          !std::isfinite(difference)) {
199	        printf("ERROR: direct Conv1 non-finite sample=%zu element=%zu\n",
200	               sample, element);
201	        cleanup();
202	        return false;
203	      }
204	      if (difference > direct_max_abs_error) {
205	        direct_max_abs_error = difference;
206	      }
207	    }
208	  }
209	
210	  *max_abs_error = direct_max_abs_error;
211	  if (direct_max_abs_error > kDirectTolerance) {
212	    printf("ERROR: direct Conv1 max_abs_error %.9g > %.9g\n",
213	           static_cast<double>(direct_max_abs_error),
214	           static_cast<double>(kDirectTolerance));
215	    cleanup();
216	    return false;
217	  }
218	
219	  cleanup();
220	  return true;
221	}
