261	    return 1;
262	  }
263	  uint8_t* tensor_arena = reinterpret_cast<uint8_t*>(
264	      (reinterpret_cast<uintptr_t>(arena_raw) + 15) &
265	      ~static_cast<uintptr_t>(15));
266	
267	  const unsigned char* model_data = model_buf;
268	  const uint8_t* input_data = input_buf;
269	  size_t input_data_size = input_size;
270	  const uint8_t* ref_data = ref_buf;
271	  size_t ref_data_size = ref_size;
272	#else
273	  (void)argc;
274	  (void)argv;
275	  uint8_t* model_buf = nullptr;
276	  uint8_t* input_buf = nullptr;
277	  uint8_t* ref_buf = nullptr;
278	  uint8_t* arena_raw = nullptr;
279	  uint8_t* tensor_arena = g_arena;
280	
281	  const unsigned char* model_data = g_skip_s0_model;
282	  const uint8_t* input_data = g_skip_s0_input_data;
283	  size_t input_data_size = g_skip_s0_input_data_size;
284	  const uint8_t* ref_data = g_skip_s0_ref_output_data;
285	  size_t ref_data_size = g_skip_s0_ref_output_data_size;
286	  printf("Using embedded model (%d bytes)\n", (int)g_skip_s0_model_size);
287	#endif
288	
289	  auto cleanup_main = [&]() {
290	    free(arena_raw);
291	    free(ref_buf);
292	    free(input_buf);
293	    free(model_buf);
294	  };
295	
296	#if defined(__NuttX__) && \
297	    defined(CONFIG_MLEARNING_CMSIS_NN_PNET_V3_CONV1_F32)
298	  float direct_conv1_max_abs_error = 0.0f;
299	  const char* direct_input_file =
300	      argc > 4 ? argv[4] : "pnet_v3_conv1_input.bin";
301	  const char* direct_filter_file =
302	      argc > 5 ? argv[5] : "pnet_v3_conv1_filter.bin";
303	  const char* direct_bias_file =
304	      argc > 6 ? argv[6] : "pnet_v3_conv1_bias.bin";
305	  if (!RunDirectConv1Comparison(direct_input_file, direct_filter_file,
306	                                direct_bias_file,
307	                                &direct_conv1_max_abs_error)) {
308	    cleanup_main();
309	    return 1;
310	  }
311	#endif
312	
313	  const tflite::Model* model = tflite::GetModel(model_data);
314	  if (!model) {
315	    printf("ERROR: GetModel failed\n");
316	    cleanup_main();
317	    return 1;
318	  }
319	
320	  tflite::MicroMutableOpResolver<14> resolver;
321	  resolver.AddAdd();
322	  resolver.AddAveragePool2D();
323	  resolver.AddConcatenation();
324	  resolver.AddConv2D();
325	  resolver.AddExpandDims();
326	  resolver.AddFullyConnected();
327	  resolver.AddLogistic();
328	  resolver.AddMean();
329	  resolver.AddMul();
330	  resolver.AddPad();
331	  resolver.AddReshape();
332	  resolver.AddStridedSlice();
333	  resolver.AddSum();
334	  resolver.AddTranspose();
335	
336	  tflite::MicroInterpreter interp(model, resolver, tensor_arena, kArenaSize);
337	  if (interp.AllocateTensors() != kTfLiteOk) {
338	    printf("ERROR: AllocateTensors failed\n");
339	    cleanup_main();
340	    return 1;
341	  }
342	  const size_t arena_used_bytes = interp.arena_used_bytes();
343	  printf("[hr_pnet] arena=%d/%d (%.1f%%)\n",
344	         (int)arena_used_bytes, (int)kArenaSize,
345	         100.0f * arena_used_bytes / kArenaSize);
346	
347	  TfLiteTensor* input = interp.input_tensor(0);
348	  TfLiteTensor* output = interp.output_tensor(0);
349	  if (input == nullptr || output == nullptr) {
350	    printf("ERROR: missing input or output tensor\n");
351	    cleanup_main();
352	    return 1;
353	  }
354	
355	  const size_t input_sample_bytes = input->bytes;
356	  const size_t output_sample_bytes = output->bytes;
357	  if (input_sample_bytes == 0 || output_sample_bytes == 0 ||
358	      output_sample_bytes % sizeof(float) != 0 ||
359	      input_data_size % input_sample_bytes != 0 ||
360	      ref_data_size % output_sample_bytes != 0) {
361	    printf("ERROR: invalid regression sizes input_file=%zu input_sample=%zu "
362	           "ref_file=%zu output_sample=%zu\n",
363	           input_data_size, input_sample_bytes, ref_data_size,
364	           output_sample_bytes);
365	    cleanup_main();
366	    return 1;
367	  }
368	
369	  const size_t input_samples = input_data_size / input_sample_bytes;
370	  const size_t reference_samples = ref_data_size / output_sample_bytes;
371	  if (input_samples == 0 || input_samples != reference_samples) {
372	    printf("ERROR: regression sample mismatch input=%zu reference=%zu\n",
373	           input_samples, reference_samples);
374	    cleanup_main();
375	    return 1;
376	  }
377	  const size_t regression_samples = input_samples;
378	  const size_t output_elements = output_sample_bytes / sizeof(float);
379	
380	  float regression_max_abs_error = 0.0f;
381	  size_t worst_sample = 0;
382	  size_t worst_element = 0;
383	  float worst_got = 0.0f;
384	  float worst_reference = 0.0f;
385	  for (size_t sample = 0; sample < regression_samples; ++sample) {
386	    memcpy(input->data.raw, input_data + sample * input_sample_bytes,
387	           input_sample_bytes);
388	    if (interp.Invoke() != kTfLiteOk) {
389	      printf("ERROR: regression Invoke failed at sample %zu\n", sample);
390	      cleanup_main();
391	      return 1;
392	    }
393	
394	    const float* got = reinterpret_cast<const float*>(output->data.raw);
395	    const float* reference = reinterpret_cast<const float*>(
396	        ref_data + sample * output_sample_bytes);
397	    for (size_t element = 0; element < output_elements; ++element) {
398	      const float difference = std::fabs(got[element] - reference[element]);
399	      if (!std::isfinite(got[element]) ||
400	          !std::isfinite(reference[element]) ||
401	          !std::isfinite(difference)) {
402	        printf("ERROR: regression non-finite sample=%zu element=%zu\n",
403	               sample, element);
404	        cleanup_main();
405	        return 1;
406	      }
407	      if (difference > regression_max_abs_error) {
408	        regression_max_abs_error = difference;
409	        worst_sample = sample;
410	        worst_element = element;
411	        worst_got = got[element];
412	        worst_reference = reference[element];
413	      }
414	    }
415	  }
416	
417	  printf("[hr_pnet] regression samples=%zu max_abs_error=%.9g "
418	         "worst_sample=%zu worst_element=%zu got=%.9g ref=%.9g\n",
419	         regression_samples, static_cast<double>(regression_max_abs_error),
420	         worst_sample, worst_element, static_cast<double>(worst_got),
421	         static_cast<double>(worst_reference));
422	
423	  constexpr float kTolerance = 1e-2f;
424	  if (regression_max_abs_error > kTolerance) {
425	    printf("FAIL: max_abs_diff %.6f > %.6f\n",
426	           static_cast<double>(regression_max_abs_error),
427	           static_cast<double>(kTolerance));
428	    cleanup_main();
429	    return 1;
430	  }
