432	#if defined(__NuttX__) && \
433	    defined(CONFIG_MLEARNING_CMSIS_NN_PNET_V3_CONV1_PROFILE)
434	  bool warmup_failed = false;
435	  int warmup_failed_index = -1;
436	  for (int i = 0; i < 10; ++i) {
437	    memcpy(input->data.raw, input_data, input_sample_bytes);
438	    if (interp.Invoke() != kTfLiteOk) {
439	      warmup_failed = true;
440	      warmup_failed_index = i;
441	      break;
442	    }
443	  }
444	  if (warmup_failed) {
445	    printf("ERROR: profile warmup Invoke failed at iteration %d\n",
446	           warmup_failed_index);
447	    cleanup_main();
448	    return 1;
449	  }
450	
451	  tflite::ResetPnetV3Conv1F32Profile();
452	  uint32_t invoke_ticks[100] = {};
453	  bool measured_invoke_failed = false;
454	  int measured_invoke_failed_index = -1;
455	  for (int i = 0; i < 100; ++i) {
456	    memcpy(input->data.raw, input_data, input_sample_bytes);
457	    const uint32_t start_ticks = tflite::GetCurrentTimeTicks();
458	    const TfLiteStatus status = interp.Invoke();
459	    invoke_ticks[i] = tflite::GetCurrentTimeTicks() - start_ticks;
460	    if (status != kTfLiteOk) {
461	      measured_invoke_failed = true;
462	      measured_invoke_failed_index = i;
463	      break;
464	    }
465	  }
466	  if (measured_invoke_failed) {
467	    printf("ERROR: measured Invoke failed at iteration %d\n",
468	           measured_invoke_failed_index);
469	    cleanup_main();
470	    return 1;
471	  }
472	
473	  const tflite::PnetV3Conv1F32Profile profile =
474	      tflite::GetPnetV3Conv1F32Profile();
475	  bool counters_valid =
476	      profile.matched_calls == 400 && profile.recorded_calls == 400 &&
477	      profile.fallback_count == 0 && profile.cmsis_error_count == 0;
478	#if defined(CONFIG_MLEARNING_CMSIS_NN_PNET_V3_CONV1_F32)
479	  counters_valid = counters_valid && profile.fast_path_hits == 400;
480	#else
481	  counters_valid = counters_valid && profile.fast_path_hits == 0;
482	#endif
483	  if (!counters_valid) {
484	    printf("ERROR: profile counters matched=%lu fast=%lu fallback=%lu "
485	           "error=%lu recorded=%lu\n",
486	           static_cast<unsigned long>(profile.matched_calls),
487	           static_cast<unsigned long>(profile.fast_path_hits),
488	           static_cast<unsigned long>(profile.fallback_count),
489	           static_cast<unsigned long>(profile.cmsis_error_count),
490	           static_cast<unsigned long>(profile.recorded_calls));
491	    cleanup_main();
492	    return 1;
493	  }
494	
495	  uint32_t stage0_ticks[100] = {};
496	  for (int group = 0; group < 100; ++group) {
497	    const int first_call = 4 * group;
498	    stage0_ticks[group] = profile.call_ticks[first_call] +
499	                          profile.call_ticks[first_call + 1] +
500	                          profile.call_ticks[first_call + 2] +
501	                          profile.call_ticks[first_call + 3];
502	  }
503	
504	  uint32_t sorted_invoke_ticks[100];
