19	static uint8_t* ReadFile(const char* path, size_t* out_size) {
20	  FILE* f = fopen(path, "rb");
21	  if (!f) {
22	    printf("Cannot open %s\n", path);
23	    return nullptr;
24	  }
25	  fseek(f, 0, SEEK_END);
26	  long sz = ftell(f);
27	  fseek(f, 0, SEEK_SET);
28	  uint8_t* buf = static_cast<uint8_t*>(malloc(sz));
29	  if (!buf) {
30	    printf("malloc(%ld) failed for %s\n", sz, path);
31	    fclose(f);
32	    return nullptr;
33	  }
34	  size_t rd = fread(buf, 1, sz, f);
35	  fclose(f);
36	  if (rd != static_cast<size_t>(sz)) {
37	    printf("Read %zu/%ld bytes from %s\n", rd, sz, path);
38	    free(buf);
39	    return nullptr;
40	  }
41	  *out_size = static_cast<size_t>(sz);
42	  return buf;
43	}
