45	static int RunTest(const char* label, const char* model_path,
46	                   const char* input_path, const char* ref_path,
47	                   float tolerance) {
48	  printf("\n=== %s ===\n", label);
49	
50	  size_t model_size = 0;
51	  uint8_t* model_buf = ReadFile(model_path, &model_size);
52	  if (!model_buf) return 1;
53	  printf("Model: %zu bytes\n", model_size);
54	
55	  const tflite::Model* model = tflite::GetModel(model_buf);
56	  if (!model) {
57	    printf("GetModel FAILED\n");
58	    free(model_buf);
59	    return 1;
60	  }
61	
62	  size_t input_size = 0;
63	  uint8_t* input_buf = ReadFile(input_path, &input_size);
64	  if (!input_buf) { free(model_buf); return 1; }
65	
66	  size_t ref_size = 0;
67	  uint8_t* ref_buf = ReadFile(ref_path, &ref_size);
68	  if (!ref_buf) { free(input_buf); free(model_buf); return 1; }
69	
70	  tflite::MicroMutableOpResolver<5> resolver;
71	  resolver.AddFullyConnected();
72	  resolver.AddElu();
73	  resolver.AddSoftmax();
74	  TFLMRegistration bigru_reg = tflite::Register_BIDIRECTIONAL_SEQUENCE_GRU();
75	  resolver.AddCustom("BIDIRECTIONAL_SEQUENCE_GRU", &bigru_reg);
76	  TFLMRegistration ln_reg = tflite::Register_LAYER_NORM();
77	  resolver.AddCustom("LAYER_NORM", &ln_reg);
78	
79	  uint8_t* arena_raw = static_cast<uint8_t*>(malloc(kArenaSize + 15));
80	  if (!arena_raw) {
81	    printf("malloc arena (%zu) FAILED\n", kArenaSize);
82	    free(ref_buf); free(input_buf); free(model_buf);
83	    return 1;
84	  }
85	  uint8_t* tensor_arena = reinterpret_cast<uint8_t*>(
86	      (reinterpret_cast<uintptr_t>(arena_raw) + 15) & ~static_cast<uintptr_t>(15));
87	
88	  tflite::MicroInterpreter interp(model, resolver, tensor_arena, kArenaSize);
89	  if (interp.AllocateTensors() != kTfLiteOk) {
90	    printf("AllocateTensors FAILED\n");
91	    free(arena_raw); free(ref_buf); free(input_buf); free(model_buf);
92	    return 1;
93	  }
94	  printf("Arena: %d/%d bytes\n", (int)interp.arena_used_bytes(),
95	         (int)kArenaSize);
96	
97	  TfLiteTensor* input = interp.input_tensor(0);
98	  if (!input || input->bytes != input_size) {
99	    printf("Input mismatch: got=%d expected=%zu\n",
100	           input ? (int)input->bytes : -1, input_size);
101	    free(arena_raw); free(ref_buf); free(input_buf); free(model_buf);
102	    return 1;
103	  }
104	  memcpy(input->data.raw, input_buf, input->bytes);
105	
106	  if (interp.Invoke() != kTfLiteOk) {
107	    printf("Invoke FAILED\n");
108	    free(ref_buf); free(input_buf); free(model_buf);
109	    return 1;
110	  }
111	
112	  const TfLiteTensor* output = interp.output_tensor(0);
113	  const float* got = reinterpret_cast<const float*>(output->data.raw);
114	  const float* ref = reinterpret_cast<const float*>(ref_buf);
115	  const int n = output->bytes / sizeof(float);
116	
117	  float max_diff = 0, sum_diff = 0;
118	  for (int i = 0; i < n; ++i) {
119	    float d = std::fabs(got[i] - ref[i]);
120	    if (d > max_diff) max_diff = d;
121	    sum_diff += d;
122	  }
123	
124	  printf("max_diff=%.6e mean_diff=%.6e\n", static_cast<double>(max_diff),
125	         static_cast<double>(sum_diff / n));
126	  printf("out[0:4]: %.6f %.6f %.6f %.6f\n", static_cast<double>(got[0]),
127	         static_cast<double>(got[1]), static_cast<double>(got[2]),
128	         static_cast<double>(got[3]));
129	  printf("ref[0:4]: %.6f %.6f %.6f %.6f\n", static_cast<double>(ref[0]),
130	         static_cast<double>(ref[1]), static_cast<double>(ref[2]),
131	         static_cast<double>(ref[3]));
132	  free(ref_buf);
133	
134	  constexpr int kRuns = 5;
135	  struct timespec t0, t1;
136	  clock_gettime(CLOCK_MONOTONIC, &t0);
137	  for (int i = 0; i < kRuns; ++i) {
138	    memcpy(input->data.raw, input_buf, input->bytes);
139	    interp.Invoke();
140	  }
141	  clock_gettime(CLOCK_MONOTONIC, &t1);
142	  long total_ms = (t1.tv_sec - t0.tv_sec) * 1000 +
143	                  (t1.tv_nsec - t0.tv_nsec) / 1000000;
144	  printf("[%s] %d runs  total=%ld ms  avg=%.1f ms\n",
145	         label, kRuns, total_ms, (float)total_ms / kRuns);
146	
147	  free(input_buf);
148	  free(arena_raw);
149	  free(model_buf);
150	
151	  int pass = (max_diff < tolerance) ? 1 : 0;
152	  printf("[%s] %s (max_diff=%.6e, tolerance=%.6e)\n",
153	         label, pass ? "PASS" : "FAIL",
154	         static_cast<double>(max_diff), static_cast<double>(tolerance));
155	  return pass ? 0 : 1;
156	}
