283	constexpr uint32_t kCrctabLen = 256;
284	uint32_t crctab[kCrctabLen];
285	
286	void GenCRC32Table() {
287	  constexpr uint32_t kPolyN = 0xEDB88320;
288	  for (size_t index = 0; index < kCrctabLen; index++) {
289	    crctab[index] = index;
290	    for (int i = 0; i < 8; i++) {
291	      if (crctab[index] & 1) {
292	        crctab[index] = (crctab[index] >> 1) ^ kPolyN;
293	      } else {
294	        crctab[index] >>= 1;
295	      }
296	    }
297	  }
298	}
299	
300	uint32_t ComputeCRC32(const uint8_t* data, const size_t data_length) {
301	  uint32_t crc32 = ~0U;
302	
303	  for (size_t i = 0; i < data_length; i++) {
304	    // crctab is an array of 256 32-bit constants
305	    const uint32_t index = (crc32 ^ data[i]) & (kCrctabLen - 1);
306	    crc32 = (crc32 >> 8) ^ crctab[index];
307	  }
308	
309	  // invert all bits of result
310	  crc32 ^= ~0U;
311	  return crc32;
312	}
