317	    TfLiteTensor* output = interpreter->output_tensor(i);
318	    uint8_t* output_values = tflite::GetTensorData<uint8_t>(output);
319	    uint32_t crc32_value = ComputeCRC32(output_values, output->bytes);
320	    MicroPrintf("Output CRC32: 0x%X", crc32_value);
321	  }
322	}
