384	bool ValidatePnetOutput(RecordingMicroInterpreter& interpreter,
385	                        const uint8_t* reference_data,
386	                        size_t reference_size) {
387	  if (interpreter.outputs_size() != 1) {
388	    printf("ERROR: PNet benchmark requires exactly one output, got %zu\n",
389	           interpreter.outputs_size());
390	    return false;
391	  }
392	
393	  TfLiteTensor* output = interpreter.output_tensor(0);
394	  if (output == nullptr || output->type != kTfLiteFloat32 ||
395	      !TensorHasShape(output, {1, 1, 64})) {
396	    printf("ERROR: PNet output must be FLOAT32 [1,1,64]\n");
397	    return false;
398	  }
399	  if (output->bytes != reference_size ||
400	      reference_size % sizeof(float) != 0) {
401	    printf("ERROR: output size mismatch: %d vs %zu\n",
402	           static_cast<int>(output->bytes), reference_size);
403	    return false;
404	  }
405	
406	  const float* actual = reinterpret_cast<const float*>(output->data.raw);
407	  const float* reference =
408	      reinterpret_cast<const float*>(reference_data);
409	  const size_t count = reference_size / sizeof(float);
410	  if (count == 0) {
411	    printf("ERROR: empty PNet reference output\n");
412	    return false;
413	  }
414	
415	  float max_diff = 0.0f;
416	  float sum_diff = 0.0f;
417	  size_t max_index = 0;
418	  for (size_t i = 0; i < count; ++i) {
419	    if (!std::isfinite(actual[i]) || !std::isfinite(reference[i])) {
420	      printf("ERROR: non-finite output/reference at index %zu\n", i);
421	      return false;
422	    }
423	    const float diff = std::fabs(actual[i] - reference[i]);
424	    sum_diff += diff;
425	    if (diff > max_diff) {
426	      max_diff = diff;
427	      max_index = i;
428	    }
429	  }
430	
431	  printf("[hr_pnet] first8 got: ");
432	  for (size_t i = 0; i < count && i < 8; ++i) {
433	    printf("%.4f ", static_cast<double>(actual[i]));
434	  }
435	  printf("\n");
436	  printf("[hr_pnet] n=%zu max_abs_diff=%.6f mean_abs_diff=%.6f "
437	         "worst@%zu got=%.4f ref=%.4f\n",
438	         count, static_cast<double>(max_diff),
439	         static_cast<double>(sum_diff / count), max_index,
440	         static_cast<double>(actual[max_index]),
441	         static_cast<double>(reference[max_index]));
442	
443	  constexpr float kTolerance = 1e-2f;
444	  if (max_diff > kTolerance) {
445	    printf("FAIL: max_abs_diff %.6f > %.6f\n",
446	           static_cast<double>(max_diff), static_cast<double>(kTolerance));
447	    return false;
448	  }
449	
450	  printf("PASS: hr_pnet_test\n");
451	  return true;
452	}
