1	// Shared helpers for TFLM example tests.
2	//
3	// On NuttX, the test data path differs between targets:
4	//   BES real hardware: rpmsgfs / fatfs at /data/
5	//   QEMU mps3-an547:   ARM semihosting hostfs at /host/
6	//                      (real /data is a tmpfs without persistent contents
7	//                       since mps3-an547 has no virtio-blk hookup)
8	//   QEMU virt boards:  fatfs at /data/ via virtio-blk
9	//
10	// LoadDataFile() tries /data/ first then /host/ so the same source
11	// works across all targets without compile-time flags.
12	//
13	// On host (Xtensa ISS, x86 unit tests), test data is embedded in headers.
14	
15	#ifndef TENSORFLOW_LITE_MICRO_EXAMPLES_TFLM_TEST_UTIL_H_
16	#define TENSORFLOW_LITE_MICRO_EXAMPLES_TFLM_TEST_UTIL_H_
17	
18	#include <cstdint>
19	#include <cstdio>
20	#include <cstdlib>
21	
22	#if defined(__NuttX__)
23	#include <time.h>
24	#endif
25	
26	namespace tflm_test_util {
27	
28	#if defined(__NuttX__)
29	
30	inline uint8_t* ReadFile(const char* path, size_t* out_size) {
31	  FILE* f = fopen(path, "rb");
32	  if (!f) return nullptr;
33	  fseek(f, 0, SEEK_END);
34	  long sz = ftell(f);
35	  fseek(f, 0, SEEK_SET);
36	  if (sz <= 0) {
37	    fclose(f);
38	    return nullptr;
39	  }
40	  uint8_t* buf = static_cast<uint8_t*>(malloc(static_cast<size_t>(sz)));
41	  if (!buf) {
42	    printf("ERROR: malloc(%ld) failed for %s\n", sz, path);
43	    fclose(f);
44	    return nullptr;
45	  }
46	  size_t rd = fread(buf, 1, static_cast<size_t>(sz), f);
47	  fclose(f);
48	  if (rd != static_cast<size_t>(sz)) {
49	    printf("ERROR: read %zu/%ld from %s\n", rd, sz, path);
50	    free(buf);
51	    return nullptr;
52	  }
53	  *out_size = static_cast<size_t>(sz);
54	  return buf;
55	}
56	
57	inline uint8_t* LoadDataFile(const char* basename, size_t* out_size) {
58	  char path[256];
59	  snprintf(path, sizeof(path), "/data/%s", basename);
60	  uint8_t* buf = ReadFile(path, out_size);
61	  if (buf) {
62	    printf("Loaded %s from %s (%zu bytes)\n", basename, path, *out_size);
63	    return buf;
64	  }
65	  snprintf(path, sizeof(path), "/host/%s", basename);
66	  buf = ReadFile(path, out_size);
67	  if (buf) {
68	    printf("Loaded %s from %s (%zu bytes)\n", basename, path, *out_size);
69	    return buf;
70	  }
71	  printf("ERROR: cannot open %s under /data or /host\n", basename);
72	  return nullptr;
73	}
74	
75	inline int64_t NowUs() {
76	  struct timespec ts;
77	  clock_gettime(CLOCK_MONOTONIC, &ts);
78	  return static_cast<int64_t>(ts.tv_sec) * 1000000LL +
79	         ts.tv_nsec / 1000LL;
80	}
81	
82	#endif  // __NuttX__
83	
84	}  // namespace tflm_test_util
85	
86	#endif  // TENSORFLOW_LITE_MICRO_EXAMPLES_TFLM_TEST_UTIL_H_
