**新增 1a：`.npy` 解析函数**（放在 `ReadDataFile` 之后，`LoadDataFile` 之前，约第 252 行后）

```cpp
// Parse a .npy file: locate the raw data payload by skipping the numpy
// header. Returns pointer into the malloc'd buffer (from LoadDataFile) +
// sets *out_payload_size. If the file is not a .npy, returns the whole
// buffer (treats as raw binary, backward compatible).
// .npy v1: magic(6) \x93NUMPY + ver(1) + header_len(2 LE) + header + data
// .npy v2: magic(6) + ver(1) + header_len(4 LE) + header + data
bool NpyPayload(const uint8_t* buf, size_t buf_size,
                const uint8_t** out_payload, size_t* out_payload_size) {
  static const uint8_t kMagic[6] = {0x93, 'N', 'U', 'M', 'P', 'Y'};
  if (buf_size < 10 || memcmp(buf, kMagic, 6) != 0) {
    *out_payload = buf;
    *out_payload_size = buf_size;
    return false;  // not npy, use as raw
  }
  const uint8_t ver = buf[6];
  size_t header_len;
  size_t header_offset;
  if (ver == 1) {
    header_len = static_cast<size_t>(buf[7]) | (static_cast<size_t>(buf[8]) << 8);
    header_offset = 9;
  } else if (ver == 2 || ver == 3) {
    if (buf_size < 12) { *out_payload = buf; *out_payload_size = buf_size; return false; }
    header_len = static_cast<size_t>(buf[7]) | (static_cast<size_t>(buf[8]) << 8) |
                 (static_cast<size_t>(buf[9]) << 16) | (static_cast<size_t>(buf[10]) << 24);
    header_offset = 11;
  } else {
    *out_payload = buf; *out_payload_size = buf_size; return false;
  }
  size_t data_offset = header_offset + header_len;
  // header is padded to 64/128-byte align, so data_offset may have trailing spaces
  if (data_offset > buf_size) { *out_payload = buf; *out_payload_size = buf_size; return false; }
  *out_payload = buf + data_offset;
  *out_payload_size = buf_size - data_offset;
  return true;
}
```

**新增 1b：通用精度比对函数**（放在 `ValidatePnetOutput` 之后，约第 452 行后）

参照 `hr_accnet_test.cc:153-189` 的模式，但不锁 shape、按 output tensor 实际 dtype 分支：
- int8：逐元素 `|got - ref|`，tol（默认 2，与 accnet 一致）
- float32：逐元素 `fabsf(got - ref)`，tol（默认 1e-2，与 pnet 一致）
- 支持 output_size != ref_size 的报错（size mismatch）

```cpp
bool ValidateGenericOutput(tflite::MicroInterpreter& interpreter,
                           const uint8_t* reference_data,
                           size_t reference_size) {
  if (interpreter.outputs_size() != 1) {
    printf("ERROR: generic benchmark requires 1 output, got %zu\n",
           interpreter.outputs_size());
    return false;
  }
  TfLiteTensor* output = interpreter.output_tensor(0);
  if (output == nullptr) {
    printf("ERROR: null output tensor\n");
    return false;
  }
  if (output->bytes != reference_size) {
    printf("ERROR: output size mismatch: %d vs %zu (dtype=%d)\n",
           (int)output->bytes, reference_size, output->type);
    return false;
  }
  // dispatch by dtype
  if (output->type == kTfLiteInt8) {
    const int8_t* got = reinterpret_cast<const int8_t*>(output->data.raw);
    const int8_t* ref = reinterpret_cast<const int8_t*>(reference_data);
    int max_diff = 0; size_t max_idx = 0;
    for (size_t i = 0; i < reference_size; ++i) {
      int d = static_cast<int>(got[i]) - static_cast<int>(ref[i]);
      if (d < 0) d = -d;
      if (d > max_diff) { max_diff = d; max_idx = i; }
    }
    printf("[gen] n=%zu max_int8_diff=%d worst@%zu\n", reference_size, max_diff, max_idx);
    constexpr int kTol = 2;
    if (max_diff > kTol) { printf("FAIL: max_int8_diff %d > %d\n", max_diff, kTol); return false; }
    printf("PASS: generic (int8)\n");
    return true;
  } else if (output->type == kTfLiteFloat32) {
    const float* got = reinterpret_cast<const float*>(output->data.raw);
    const float* ref = reinterpret_cast<const float*>(reference_data);
    float max_diff = 0; size_t max_idx = 0; size_t count = reference_size / sizeof(float);
    for (size_t i = 0; i < count; ++i) {
      float d = std::fabs(got[i] - ref[i]);
      if (d > max_diff) { max_diff = d; max_idx = i; }
    }
    printf("[gen] n=%zu max_abs_diff=%.6f worst@%zu\n", count, (double)max_diff, max_idx);
    constexpr float kTol = 1e-2f;
    if (max_diff > kTol) { printf("FAIL: max_abs_diff %.6f > %.6f\n", (double)max_diff, (double)kTol); return false; }
    printf("PASS: generic (float32)\n");
    return true;
  } else {
    printf("ERROR: unsupported output dtype %d (only int8/float32)\n", output->type);
    return false;
  }
}
```

