注意：`NpyPayload` 返回 `const uint8_t*`，但 `SetPnetInput` 用 `memcpy(input->data.raw, input_data, input_size)` 接受 `const`。新增的 `SetGenericInput` 同样用 const 即可。**新增 `SetGenericInput`**（不锁 shape，只校验 bytes 匹配）：

```cpp
bool SetGenericInput(tflite::MicroInterpreter& interpreter,
                     const uint8_t* input_data, size_t input_size) {
  if (interpreter.inputs_size() != 1) {
    printf("ERROR: requires 1 input, got %zu\n", interpreter.inputs_size());
    return false;
  }
  TfLiteTensor* input = interpreter.input_tensor(0);
  if (input == nullptr || input->bytes != input_size) {
    printf("ERROR: input size mismatch: %d vs %zu\n",
           input ? (int)input->bytes : -1, input_size);
    return false;
  }
  memcpy(input->data.raw, input_data, input_size);
  return true;
}
```

