```cpp
bool SetGenericInput(tflite::MicroInterpreter& interpreter,
                     const uint8_t* input_data, size_t input_size) {
  size_t offset = 0;
  for (size_t i = 0; i < interpreter.inputs_size(); ++i) {
    TfLiteTensor* input = interpreter.input_tensor(i);
    if (input == nullptr) { printf("ERROR: null input %zu\n", i); return false; }
    if (offset + input->bytes > input_size) {
      printf("ERROR: input overflow at %zu (%zu + %d > %zu)\n",
             i, offset, (int)input->bytes, input_size);
      return false;
    }
    memcpy(input->data.raw, input_data + offset, input->bytes);
    offset += input->bytes;
  }
  return true;
}
```

