/* Generic, shape-agnostic input loader for mlzoo_test: copies raw bytes into
 * each input tensor in turn (1..N inputs supported).  Does not enforce a
 * fixed shape so it works for any model whose input bytes match the file
 * payload size.
 */
bool SetGenericInput(tflite::MicroInterpreter& interpreter,
                     const uint8_t* input_data, size_t input_size) {
  size_t offset = 0;
  for (size_t i = 0; i < interpreter.inputs_size(); ++i) {
    TfLiteTensor* input = interpreter.input_tensor(i);
    if (input == nullptr) {
      printf("ERROR: null input tensor %zu\n", i);
      return false;
    }
    if (offset + input->bytes > input_size) {
      printf("ERROR: input overflow at %zu (%zu + %d > %zu)\n", i, offset,
             (int)input->bytes, input_size);
      return false;
    }
    memcpy(input->data.raw, input_data + offset, input->bytes);
    offset += input->bytes;
  }
  return true;
}

/* Generic output validation for mlzoo_test: walks 1..N output tensors,
 * comparing each against the corresponding slice of the reference buffer
 * (laid out by concatenating outputs in index order).  Dispatches per
 * tensor dtype:
 *   int8    -> integer |got - ref|, tol = 2 (same as hr_accnet_test)
 *   float32 -> fabsf diff, tol = 1e-2 (same as hr_pnet/attengru_test)
 */
bool ValidateGenericOutput(tflite::MicroInterpreter& interpreter,
                           const uint8_t* reference_data,
                           size_t reference_size) {
  size_t out_offset = 0;
  int max_int8_diff = 0;
  float max_float_diff = 0.0f;
  bool is_int8 = false;
  bool is_float = false;
  int total_n = 0;
  for (size_t i = 0; i < interpreter.outputs_size(); ++i) {
    TfLiteTensor* output = interpreter.output_tensor(i);
    if (output == nullptr) {
      printf("ERROR: null output tensor %zu\n", i);
      return false;
    }
    if (out_offset + output->bytes > reference_size) {
      printf("ERROR: ref overflow at output %zu (%zu + %d > %zu)\n", i,
             out_offset, (int)output->bytes, reference_size);
      return false;
    }
    if (output->type == kTfLiteInt8) {
      is_int8 = true;
      const int8_t* got = reinterpret_cast<const int8_t*>(output->data.raw);
      const int8_t* ref =
          reinterpret_cast<const int8_t*>(reference_data + out_offset);
      const int n = (int)output->bytes;
      for (int j = 0; j < n; ++j) {
        int d = static_cast<int>(got[j]) - static_cast<int>(ref[j]);
        if (d < 0) d = -d;
        if (d > max_int8_diff) max_int8_diff = d;
      }
      total_n += n;
    } else if (output->type == kTfLiteFloat32) {
      is_float = true;
      const float* got = reinterpret_cast<const float*>(output->data.raw);
      const float* ref =
          reinterpret_cast<const float*>(reference_data + out_offset);
      const int n = (int)(output->bytes / sizeof(float));
      for (int j = 0; j < n; ++j) {
        float d = std::fabs(got[j] - ref[j]);
        if (d > max_float_diff) max_float_diff = d;
      }
      total_n += n;
    } else {
      printf("ERROR: unsupported output %zu dtype %d (only int8/float32)\n", i,
             output->type);
      return false;
    }
    out_offset += output->bytes;
  }
  if (is_int8) {
    printf("[gen] total_elems=%d max_int8_diff=%d\n", total_n,
           max_int8_diff);
    constexpr int kTol = 2;
    if (max_int8_diff > kTol) {
      printf("FAIL: max_int8_diff %d > %d\n", max_int8_diff, kTol);
      return false;
    }
    printf("PASS: generic (int8, %zu outputs)\n",
           (size_t)interpreter.outputs_size());
    return true;
  }
  if (is_float) {
    printf("[gen] total_elems=%d max_abs_diff=%.6f\n", total_n,
           (double)max_float_diff);
    constexpr float kTol = 1e-2f;
    if (max_float_diff > kTol) {
      printf("FAIL: max_abs_diff %.6f > %.6f\n", (double)max_float_diff,
             (double)kTol);
      return false;
    }
    printf("PASS: generic (float32, %zu outputs)\n",
           (size_t)interpreter.outputs_size());
    return true;
  }
  printf("ERROR: no comparable output\n");
  return false;
}

