           header_len = static_cast<size_t>(buf[7]) |
                        (static_cast<size_t>(buf[8]) << 8) |
                        (static_cast<size_t>(buf[9]) << 16) |
                        (static_cast<size_t>(buf[10]) << 24);
           header_offset = 11;
         } else {
           *out_payload = buf;
           *out_payload_size = buf_size;
           return false;
         }
         const size_t data_offset = header_offset + header_len;
         if (data_offset > buf_size) {
           *out_payload = buf;
           *out_payload_size = buf_size;
           return false;
         }
         *out_payload = buf + data_offset;
         *out_payload_size = buf_size - data_offset;
         return true;
       }
