input.new_string:
/* Locate the raw data payload inside a NumPy .npy buffer by skipping the
 * header.  If the buffer is not a .npy file, the whole buffer is returned
 * (backward compatible with raw .bin inputs).
 * numpy format (all multi-byte ints are little-endian):
 *   magic(6) \x93NUMPY + version(2: major, minor)
 *   v1.x: header_len(2 LE) + header + data   (header_offset = 10)
 *   v2.x: header_len(4 LE) + header + data   (header_offset = 12)
 *   v3.x: header_len(4 LE) + header + data   (header_offset = 12)
 * Returns true when a .npy header was recognized and stripped.
 */
bool NpyPayload(const uint8_t* buf, size_t buf_size,
                const uint8_t** out_payload, size_t* out_payload_size) {
  static const uint8_t kMagic[6] = {0x93, 'N', 'U', 'M', 'P', 'Y'};
  /* 6 (magic) + 2 (version) + 2 (v1 header_len) = 10 minimum */
  if (buf_size < 10 || memcmp(buf, kMagic, 6) != 0) {
    *out_payload = buf;
    *out_payload_size = buf_size;
    return false;  /* not npy, treat as raw binary */
  }
  const uint8_t ver_major = buf[6];
  size_t header_len;
  size_t header_offset;
  if (ver_major == 1) {
    /* version(2) at buf[6..7], header_len(2 LE) at buf[8..9] */
    header_len = static_cast<size_t>(buf[8]) |
                 (static_cast<size_t>(buf[9]) << 8);
    header_offset = 10;
  } else if (ver_major == 2 || ver_major == 3) {
    /* version(2) at buf[6..7], header_len(4 LE) at buf[8..11] */
    if (buf_size < 12) {
      *out_payload = buf;
      *out_payload_size = buf_size;
      return false;
    }
    header_len = static_cast<size_t>(buf[8]) |
                 (static_cast<size_t>(buf[9]) << 8) |
                 (static_cast<size_t>(buf[10]) << 16) |
                 (static_cast<size_t>(buf[11]) << 24);
    header_offset = 12;
  } else {
    *out_payload = buf;
    *out_payload_size = buf_size;
    return false;
  }
  const size_t data_offset = header_offset + header_len;
  if (data_offset > buf_size) {
    *out_payload = buf;
    *out_payload_size = buf_size;
    return false;
  }
  *out_payload = buf + data_offset;
  *out_payload_size = buf_size - data_offset;
  return true;
}

