61	void SymmetricQuantize(const float* input, int size, int8_t* output,
62	                       float* scale) {
63	  float min_val = input[0];
64	  float max_val = input[0];
65	  for (int i = 1; i < size; ++i) {
66	    if (input[i] < min_val) min_val = input[i];
67	    if (input[i] > max_val) max_val = input[i];
68	  }
69	  const float range = std::max(std::abs(min_val), std::abs(max_val));
70	  if (range == 0.0f) {
71	    *scale = 1.0f;
72	    std::memset(output, 0, size * sizeof(int8_t));
73	    return;
74	  }
75	  *scale = range / 127.0f;
76	  const float inv_scale = 127.0f / range;
77	  for (int i = 0; i < size; ++i) {
78	    int32_t v = static_cast<int32_t>(input[i] * inv_scale +
79	                                     (input[i] >= 0.0f ? 0.5f : -0.5f));
80	    v = v < -127 ? -127 : (v > 127 ? 127 : v);
81	    output[i] = static_cast<int8_t>(v);
82	  }
83	}
